-- =====================================================================================
-- MEDICAL CRM — SEED DATA
-- Target: the canonical schema in schema.sql (PostgreSQL 15+).
--
-- IMPORTANT: run this as the schema-owner / migration role (the same role that ran
-- the DDL), NOT as app_user. Several tables have FORCE ROW LEVEL SECURITY, and this
-- script relies on app.current_role being UNSET (so app_current_role() IS NULL and
-- every role-gated trigger/RLS branch that checks app_current_role() = 'caller' or
-- similar simply evaluates false/no-op), plus the seeding role holding BYPASSRLS so
-- FORCE ROW LEVEL SECURITY does not block these inserts. Do NOT call
-- set_app_session() before running this file.
--
-- Deliberately NOT inserted manually (populated automatically by the schema's own
-- triggers, exactly as designed):
--   * lead_assignments   <- trg_sync_lead_assignment_history, fired by leads inserts
--   * audit_log          <- log_audit(), fired on every audited table's INSERT
--   * users.assigned_leads_count <- trg_maintain_assigned_leads_count
--   * orders.total_amount        <- trg_order_items_update_total (incremental)
--   * *.search_vector             <- STORED generated columns
--   * order_items.line_total      <- STORED generated column
--   * renewals.customer_name/medicine_name/order_date and
--     orders/follow_ups.customer_name <- trigger-synced from the referenced row;
--     placeholder values below are supplied only to satisfy NOT NULL prior to the
--     BEFORE trigger firing and are expected to be overwritten.
-- =====================================================================================

BEGIN;

